DROP TABLE IF EXISTS produit;

CREATE TABLE produit (
    id INTEGER PRIMARY KEY,
    nom TEXT NOT NULL,
    prix REAL
);

SELECT name FROM sqlite_master WHERE type = 'table' AND name = 'produit';

DROP TABLE IF EXISTS employe;

CREATE TABLE employe (
    id INTEGER PRIMARY KEY,
    nom TEXT NOT NULL,
    salaire DECIMAL(10, 2),
    date_embauche DATE
);

SELECT name FROM sqlite_master WHERE type = 'table' AND name = 'employe';

DROP TABLE IF EXISTS mesure;

CREATE TABLE mesure (
    id INTEGER PRIMARY KEY,
    valeur REAL NOT NULL,
    unite TEXT DEFAULT 'kg',
    actif INTEGER DEFAULT 1
);

SELECT name, dflt_value FROM pragma_table_info('mesure');

DROP TABLE IF EXISTS cours;

CREATE TABLE cours (
    id INTEGER PRIMARY KEY,
    titre TEXT NOT NULL,
    duree INTEGER
);

SELECT name FROM sqlite_master WHERE type = 'table' AND name = 'cours';

DROP TABLE IF EXISTS cours;
CREATE TABLE cours (id INTEGER PRIMARY KEY, titre TEXT NOT NULL);

-- ALTER TABLE

DROP TABLE IF EXISTS cours;
CREATE TABLE cours (id INTEGER PRIMARY KEY, titre TEXT NOT NULL);

ALTER TABLE cours ADD COLUMN coefficient REAL DEFAULT 1.0;

SELECT name FROM pragma_table_info('cours');

DROP TABLE IF EXISTS salle;
DROP TABLE IF EXISTS salle_cours;

-- CREATE puis RENAME

DROP TABLE IF EXISTS salle;
DROP TABLE IF EXISTS salle_cours;

CREATE TABLE salle (
    id INTEGER PRIMARY KEY,
    capacite INTEGER
);

ALTER TABLE salle RENAME TO salle_cours;

SELECT name FROM sqlite_master WHERE type = 'table' AND name = 'salle_cours';

DROP TABLE IF EXISTS membre;

CREATE TABLE membre (
    id INTEGER PRIMARY KEY,
    email TEXT NOT NULL UNIQUE,
    nom TEXT NOT NULL
);

SELECT sql FROM sqlite_master WHERE type = 'table' AND name = 'membre';

DROP TABLE IF EXISTS commande;

CREATE TABLE commande (
    id INTEGER PRIMARY KEY,
    client_id INTEGER NOT NULL,
    montant REAL CHECK (montant >= 0),
    FOREIGN KEY (client_id) REFERENCES membre(id)
);

SELECT sql FROM sqlite_master WHERE type = 'table' AND name = 'commande';

DROP TABLE IF EXISTS note2;

CREATE TABLE note2 (
    etudiant_id INTEGER NOT NULL,
    matiere_id INTEGER NOT NULL,
    valeur REAL CHECK (valeur BETWEEN 0 AND 20),
    PRIMARY KEY (etudiant_id, matiere_id)
);

SELECT sql FROM sqlite_master WHERE type = 'table' AND name = 'note2';

